//! The Rust port of `wrappers.c`: safe Rust; `lib.rs` exports each function under its C name.
//!
//! The real CRC functions from lib/crc/ are ported as private helpers over
//! `&[u8]`; the public functions mirror the C wrappers driving them on
//! seeded buffers. Lookup tables are generated by const fns mirroring the
//! kernel's own build-time generators (gen_crc32table.c, gen_crc64table.c)
//! and bitwise table generation for the small tables — the record/diff
//! pipeline proves the generated tables identical to the shipped ones.

#![forbid(unsafe_code)]

const BUFSZ: usize = 512;

/* xorshift64: identical stream to the C reference. */
fn xorshift(state: &mut u64) -> u64 {
    let mut x = *state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    *state = x;
    x
}

/// `buf_len()`: defined-behavior absolute value, len % (BUFSZ+1).
fn buf_len(len: i64) -> usize {
    ((if len < 0 { len.wrapping_neg() } else { len }) as usize) % (BUFSZ + 1)
}

fn fill(seed: u64) -> [u8; BUFSZ] {
    let mut s = seed | 1;
    let mut buf = [0u8; BUFSZ];
    for b in &mut buf {
        *b = xorshift(&mut s) as u8;
    }
    buf
}

// ---- table generators (mirroring the kernel's build-time generators) ---

/// `crc32init_le_generic` from gen_crc32table.c.
const fn crc32_init_le(poly: u32) -> [u32; 256] {
    let mut tab = [0u32; 256];
    let mut crc: u32 = 1;
    let mut i = 128usize;
    while i != 0 {
        crc = (crc >> 1) ^ if crc & 1 != 0 { poly } else { 0 };
        let mut j = 0;
        while j < 256 {
            tab[i + j] = crc ^ tab[j];
            j += 2 * i;
        }
        i >>= 1;
    }
    tab
}

/// `crc32init_be` from gen_crc32table.c (poly 0x04c11db7).
const fn crc32_init_be() -> [u32; 256] {
    const POLY: u32 = 0x04c11db7;
    let mut tab = [0u32; 256];
    let mut crc: u32 = 0x80000000;
    let mut i = 1usize;
    while i < 256 {
        crc = (crc << 1) ^ if crc & 0x80000000 != 0 { POLY } else { 0 };
        let mut j = 0;
        while j < i {
            tab[i + j] = crc ^ tab[j];
            j += 1;
        }
        i <<= 1;
    }
    tab
}

/// `generate_crc64_table` from gen_crc64table.c (ECMA-182 poly, msb-first).
const fn crc64_init() -> [u64; 256] {
    const POLY: u64 = 0x42F0E1EBA9EA3693;
    let mut tab = [0u64; 256];
    let mut i = 0u64;
    while i < 256 {
        let mut crc: u64 = 0;
        let mut c = i << 56;
        let mut j = 0;
        while j < 8 {
            crc = if (crc ^ c) & 0x8000000000000000 != 0 {
                (crc << 1) ^ POLY
            } else {
                crc << 1
            };
            c <<= 1;
            j += 1;
        }
        tab[i as usize] = crc;
        i += 1;
    }
    tab
}

/// `generate_reflected_crc64_table` from gen_crc64table.c (NVMe poly).
const fn crc64_nvme_init() -> [u64; 256] {
    const POLY: u64 = 0x9A6C9329AC4BC9B5;
    let mut tab = [0u64; 256];
    let mut i = 0u64;
    while i < 256 {
        let mut crc: u64 = 0;
        let c = i;
        let mut j = 0;
        while j < 8 {
            crc = if (crc ^ (c >> j)) & 1 != 0 {
                (crc >> 1) ^ POLY
            } else {
                crc >> 1
            };
            j += 1;
        }
        tab[i as usize] = crc;
        i += 1;
    }
    tab
}

/// Reflected u16 table, bitwise generation (crc16 poly 0xA001, ccitt 0x8408).
const fn table16_le(poly: u16) -> [u16; 256] {
    let mut tab = [0u16; 256];
    let mut i = 0usize;
    while i < 256 {
        let mut crc = i as u16;
        let mut j = 0;
        while j < 8 {
            crc = (crc >> 1) ^ if crc & 1 != 0 { poly } else { 0 };
            j += 1;
        }
        tab[i] = crc;
        i += 1;
    }
    tab
}

/// Big-endian u16 table, bitwise generation (itu-t 0x1021, t10dif 0x8bb7).
const fn table16_be(poly: u16) -> [u16; 256] {
    let mut tab = [0u16; 256];
    let mut i = 0usize;
    while i < 256 {
        let mut crc = (i as u16) << 8;
        let mut j = 0;
        while j < 8 {
            crc = (crc << 1) ^ if crc & 0x8000 != 0 { poly } else { 0 };
            j += 1;
        }
        tab[i] = crc;
        i += 1;
    }
    tab
}

/// crc7_be_syndrome_table: big-endian, poly x^7+x^3+1 aligned <<1 (0x12).
const fn crc7_init() -> [u8; 256] {
    const POLY: u8 = 0x12;
    let mut tab = [0u8; 256];
    let mut i = 0usize;
    while i < 256 {
        let mut crc = i as u8;
        let mut j = 0;
        while j < 8 {
            crc = (crc << 1) ^ if crc & 0x80 != 0 { POLY } else { 0 };
            j += 1;
        }
        tab[i] = crc;
        i += 1;
    }
    tab
}

static CRC32_TABLE_LE: [u32; 256] = crc32_init_le(0xedb88320);
static CRC32_TABLE_BE: [u32; 256] = crc32_init_be();
static CRC32C_TABLE_LE: [u32; 256] = crc32_init_le(0x82f63b78);
static CRC64_TABLE: [u64; 256] = crc64_init();
static CRC64_NVME_TABLE: [u64; 256] = crc64_nvme_init();
static CRC16_TABLE: [u16; 256] = table16_le(0xa001);
static CRC_CCITT_TABLE: [u16; 256] = table16_le(0x8408);
static CRC_ITU_T_TABLE: [u16; 256] = table16_be(0x1021);
static T10_DIF_CRC_TABLE: [u16; 256] = table16_be(0x8bb7);
static CRC7_BE_SYNDROME_TABLE: [u8; 256] = crc7_init();

// ---- the real CRC functions (ports of lib/crc/*.c) ---------------------

/// `crc32_le_base` — reflected CRC32, table-driven.
fn crc32_le(mut crc: u32, p: &[u8]) -> u32 {
    for &b in p {
        crc = (crc >> 8) ^ CRC32_TABLE_LE[((crc & 255) ^ b as u32) as usize];
    }
    crc
}

/// `crc32_be_base` — big-endian CRC32.
fn crc32_be(mut crc: u32, p: &[u8]) -> u32 {
    for &b in p {
        crc = (crc << 8) ^ CRC32_TABLE_BE[((crc >> 24) ^ b as u32) as usize];
    }
    crc
}

/// `crc32c_base` — reflected Castagnoli CRC32.
fn crc32c(mut crc: u32, p: &[u8]) -> u32 {
    for &b in p {
        crc = (crc >> 8) ^ CRC32C_TABLE_LE[((crc & 255) ^ b as u32) as usize];
    }
    crc
}

/// `crc64_be_generic` — ECMA-182 CRC64.
fn crc64_be(mut crc: u64, p: &[u8]) -> u64 {
    for &b in p {
        crc = (crc << 8) ^ CRC64_TABLE[((crc >> 56) ^ b as u64) as usize];
    }
    crc
}

/// `crc64_nvme` — NVMe reflected CRC64 with ~crc in/out.
fn crc64_nvme(crc: u64, p: &[u8]) -> u64 {
    let mut crc = !crc;
    for &b in p {
        crc = (crc >> 8) ^ CRC64_NVME_TABLE[((crc & 0xff) ^ b as u64) as usize];
    }
    !crc
}

/// `crc16` — poly 0x8005 reflected.
fn crc16(mut crc: u16, p: &[u8]) -> u16 {
    for &b in p {
        crc = (crc >> 8) ^ CRC16_TABLE[((crc & 0xff) ^ b as u16) as usize];
    }
    crc
}

/// `crc_ccitt` — per-byte helper `crc_ccitt_byte`.
fn crc_ccitt(mut crc: u16, p: &[u8]) -> u16 {
    for &b in p {
        crc = (crc >> 8) ^ CRC_CCITT_TABLE[((crc ^ b as u16) & 0xff) as usize];
    }
    crc
}

/// `crc_itu_t` — per-byte helper `crc_itu_t_byte`.
fn crc_itu_t(mut crc: u16, p: &[u8]) -> u16 {
    for &b in p {
        crc = (crc << 8) ^ CRC_ITU_T_TABLE[(((crc >> 8) ^ b as u16) & 0xff) as usize];
    }
    crc
}

/// `crc7_be` — syndrome table, crc^byte index.
fn crc7_be(mut crc: u8, p: &[u8]) -> u8 {
    for &b in p {
        crc = CRC7_BE_SYNDROME_TABLE[(crc ^ b) as usize];
    }
    crc
}

/// `crc_t10dif_update`/`crc_t10dif_generic` — big-endian T10 DIF CRC.
fn crc_t10dif_update(mut crc: u16, p: &[u8]) -> u16 {
    for &b in p {
        crc = (crc << 8) ^ T10_DIF_CRC_TABLE[((crc >> 8) ^ b as u16) as usize];
    }
    crc
}

/// `crc8_populate_msb` — table for polynomial in reverse bit order.
fn crc8_populate_msb(table: &mut [u8; 256], polynomial: u8) {
    const MSBIT: u8 = 0x80;
    let mut t = MSBIT;

    table[0] = 0;
    let mut i = 1usize;
    while i < 256 {
        t = (t << 1) ^ if t & MSBIT != 0 { polynomial } else { 0 };
        let mut j = 0;
        while j < i {
            table[i + j] = table[j] ^ t;
            j += 1;
        }
        i *= 2;
    }
}

/// `crc8_populate_lsb` — table for polynomial in regular bit order.
fn crc8_populate_lsb(table: &mut [u8; 256], polynomial: u8) {
    let mut t = 1u8;

    table[0] = 0;
    let mut i = 128usize;
    while i != 0 {
        t = (t >> 1) ^ if t & 1 != 0 { polynomial } else { 0 };
        let mut j = 0;
        while j < 256 {
            table[i + j] = table[j] ^ t;
            j += 2 * i;
        }
        i >>= 1;
    }
}

/// `crc8` — running CRC8 over a caller-supplied table.
fn crc8(table: &[u8; 256], p: &[u8], mut crc: u8) -> u8 {
    for &b in p {
        crc = table[(crc ^ b) as usize];
    }
    crc
}

// ---- wrapper functions (mirror wrappers.c) -----------------------------

/// Port of `uint64_t wrap_crc32_le(uint64_t, uint64_t, int64_t)`.
pub fn wrap_crc32_le(crc: u64, seed: u64, len: i64) -> u64 {
    let n = buf_len(len);
    let buf = fill(seed);
    crc32_le(crc as u32, &buf[..n]) as u64
}

/// Port of `uint64_t wrap_crc32_be(uint64_t, uint64_t, int64_t)`.
pub fn wrap_crc32_be(crc: u64, seed: u64, len: i64) -> u64 {
    let n = buf_len(len);
    let buf = fill(seed);
    crc32_be(crc as u32, &buf[..n]) as u64
}

